<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, shallowRef, watch } from 'vue'
import type * as Monaco from 'monaco-editor/esm/vs/editor/editor.api'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Close, Document, Folder, Plus, Search } from '@element-plus/icons-vue'
import { dataSourceApi } from '../../api/platform'
import { developmentApi, metadataApi, releaseApi, type DataSourceView, type DevFile, type DevProject, type DevelopmentBundle, type DevelopmentBundleRelease, type DevelopmentSchedule, type FileVersion, type LineageView, type QueryResult } from '../../api/domain'

const projects=ref<DevProject[]>([]), files=ref<DevFile[]>([]), sources=ref<DataSourceView[]>([]), databases=ref<string[]>([])
const projectId=ref<number>(), file=ref<DevFile>(), openFiles=ref<DevFile[]>([]), sourceId=ref<number>(), database=ref('')
const editorHost=ref<HTMLElement>(), editor=shallowRef<Monaco.editor.IStandaloneCodeEditor>(), editorLoading=ref(false), running=ref(false), saving=ref(false)
const sqlDirty=ref(false), treeSearch=ref(''), groupMode=ref<'all'|'recent'|'mine'>('all'), activeBottom=ref<'result'|'log'|'lineage'|'schedule'|'versions'>('result')
const result=ref<QueryResult>(), logText=ref('暂无执行日志'), lineage=ref<LineageView[]>([]), versions=ref<FileVersion[]>([])
const schedule=ref<DevelopmentSchedule>(), bundle=ref<DevelopmentBundle>(), releases=ref<DevelopmentBundleRelease[]>([])
const scheduleOpen=ref(false), infoOpen=ref(false), scheduleSaving=ref(false), publishOpen=ref(false), releaseDetailOpen=ref(false), selectedRelease=ref<DevelopmentBundleRelease>()
const newTaskOpen=ref(false), newTask=reactive({name:'',layer:'DWD',description:'',configureSchedule:false})
const publishRemark=ref('统一发布 SQL 与调度配置')
const scheduleForm=reactive({enabled:false,cycleType:'DAILY',executionTime:'02:00',cronExpression:'0 0 2 * * ?',timezone:'Asia/Shanghai',dataSourceId:undefined as number|undefined,databaseName:'',bizDateParam:'${system.biz.date-1}',retryTimes:3,retryIntervalMinutes:5,timeoutMinutes:120,upstreamFileIds:[] as number[]})
let monacoApi:typeof import('monaco-editor/esm/vs/editor/editor.api')|null=null
let applyingContent=false

const layerOrder=['ODS','DWD','DWS','ADS','OTHER']
function layerOf(name:string){const v=name.replace(/\.sql$/i,'').toUpperCase();return layerOrder.find(x=>x!=='OTHER'&&v.startsWith(x+'_'))||'OTHER'}
const visibleFiles=computed(()=>files.value.filter(x=>!treeSearch.value.trim()||x.name.toLowerCase().includes(treeSearch.value.trim().toLowerCase())))
const groupedFiles=computed(()=>layerOrder.map(layer=>({layer,rows:visibleFiles.value.filter(x=>layerOf(x.name)===layer)})).filter(x=>x.rows.length))
const currentName=computed(()=>file.value?.name.replace(/\.sql$/i,'')||'未打开任务')
const unsavedCount=computed(()=>Number(sqlDirty.value||bundle.value?.sqlDirty)+Number(bundle.value?.scheduleDirty))
const upstreamOptions=computed(()=>files.value.filter(x=>x.id!==file.value?.id))
const scheduleDependencies=computed(()=>schedule.value?.dependencies||[])
const scheduleDownstream=computed(()=>schedule.value?.downstream||[])
const currentSourceName=computed(()=>sources.value.find(x=>x.id===sourceId.value)?.name||'未选择 StarRocks')
const publishedSql=computed(()=>bundle.value?.publishedSqlVersion||0)
const publishedSchedule=computed(()=>bundle.value?.publishedScheduleVersion||0)

function msg(e:unknown){return e instanceof Error?e.message:'操作失败'}
function fmt(v?:string){return v?v.replace('T',' ').slice(0,19):'—'}
function cycleLabel(v:string){return ({DAILY:'每日',HOURLY:'每小时',WEEKLY:'每周',MONTHLY:'每月',CRON:'自定义 Cron'} as Record<string,string>)[v]||v}
function stateClass(f:DevFile){if(f.id===file.value?.id&&sqlDirty.value)return'dirty';return f.status==='PUBLISHED'?'ok':'dirty'}

async function initEditor(){if(!editorHost.value||editor.value||editorLoading.value)return;editorLoading.value=true;try{monacoApi??=await import('monaco-editor/esm/vs/editor/editor.api');await import('monaco-editor/esm/vs/basic-languages/sql/sql.contribution');if(!editorHost.value)return;editor.value=monacoApi.editor.create(editorHost.value,{value:file.value?.content||'-- 请选择开发任务',language:'sql',theme:'vs',automaticLayout:true,minimap:{enabled:false},fontSize:13,lineHeight:24,scrollBeyondLastLine:false,padding:{top:14},renderLineHighlight:'line'});editor.value.addCommand(monacoApi.KeyMod.CtrlCmd|monacoApi.KeyCode.Enter,()=>void runSql());editor.value.addCommand(monacoApi.KeyMod.CtrlCmd|monacoApi.KeyCode.KeyS,()=>void saveSql());editor.value.onDidChangeModelContent(()=>{if(!applyingContent)sqlDirty.value=true})}catch(e){ElMessage.error('SQL 编辑器加载失败：'+msg(e))}finally{editorLoading.value=false}}
function setEditorContent(v:string){if(!editor.value)return;applyingContent=true;editor.value.setValue(v||'');sqlDirty.value=false;queueMicrotask(()=>applyingContent=false)}

async function boot(){try{const [ps,ds]=await Promise.all([developmentApi.projects(),dataSourceApi.list()]);projects.value=ps;sources.value=ds.filter(x=>x.type==='STARROCKS');projectId.value=ps[0]?.id;sourceId.value=sources.value[0]?.id;if(sourceId.value)await loadDatabases();if(projectId.value)await loadFiles();await nextTick();void initEditor()}catch(e){ElMessage.error(msg(e))}}
async function loadFiles(preferred?:number){if(!projectId.value)return;files.value=await developmentApi.files(projectId.value);const target=files.value.find(x=>x.id===preferred)||file.value&&files.value.find(x=>x.id===file.value?.id)||files.value[0];if(target)await openFile(target)}
async function loadDatabases(){if(!sourceId.value)return;const rows=await metadataApi.databases(sourceId.value,'STARROCKS');databases.value=rows.map(x=>x.name);if(!databases.value.includes(database.value))database.value=databases.value[0]||''}
async function openFile(row:DevFile){if(sqlDirty.value&&file.value?.id!==row.id){try{await ElMessageBox.confirm('当前 SQL 有未保存修改，仍然切换任务吗？','切换任务',{type:'warning'})}catch{return}}const detail=await developmentApi.getFile(row.id);file.value=detail;const idx=openFiles.value.findIndex(x=>x.id===detail.id);if(idx<0)openFiles.value.push(detail);else openFiles.value[idx]=detail;setEditorContent(detail.content);await loadTaskMeta()}
async function loadTaskMeta(){if(!file.value)return;const [s,b,r,v]=await Promise.all([developmentApi.schedule(file.value.id),developmentApi.bundle(file.value.id),developmentApi.bundleReleases(file.value.id),developmentApi.versions(file.value.id)]);schedule.value=s;bundle.value=b;releases.value=r;versions.value=v;if(s.dataSourceId&&sources.value.some(x=>x.id===s.dataSourceId)){sourceId.value=s.dataSourceId;await loadDatabases();database.value=s.databaseName||database.value}fillSchedule(s);void loadLineage()}
function fillSchedule(s:DevelopmentSchedule){Object.assign(scheduleForm,{enabled:s.enabled,cycleType:s.cycleType||'DAILY',executionTime:s.executionTime||'02:00',cronExpression:s.cronExpression||'0 0 2 * * ?',timezone:s.timezone||'Asia/Shanghai',dataSourceId:s.dataSourceId||sourceId.value,databaseName:s.databaseName||database.value,bizDateParam:s.bizDateParam||'${system.biz.date-1}',retryTimes:s.retryTimes??3,retryIntervalMinutes:s.retryIntervalMinutes??5,timeoutMinutes:s.timeoutMinutes??120,upstreamFileIds:s.dependencies.map(x=>x.fileId)})}

async function saveSql(){if(!file.value||!editor.value)return;saving.value=true;try{file.value=await developmentApi.saveFile(file.value.id,{content:editor.value.getValue(),name:file.value.name,description:file.value.description});sqlDirty.value=false;ElMessage.success(`SQL 已保存为 V${file.value.currentVersion}，等待统一发布`);await refreshBundle()}catch(e){ElMessage.error(msg(e))}finally{saving.value=false}}
async function runSql(){if(!sourceId.value||!editor.value)return ElMessage.warning('请选择 StarRocks 数据源');running.value=true;activeBottom.value='log';logText.value='正在提交 SQL 到 StarRocks...';try{const sql=editor.value.getModel()?.getValue()||'';result.value=await developmentApi.query(sql,sourceId.value,database.value||undefined);logText.value=`[${new Date().toLocaleTimeString()}] 提交 SQL 到 ${currentSourceName.value}\n数据库：${database.value||'—'}\n执行成功，返回 ${result.value.rowCount} 行\n总耗时 ${result.value.elapsedMs} ms`;activeBottom.value='result';ElMessage.success('SQL 执行成功')}catch(e){logText.value=msg(e);ElMessage.error(msg(e))}finally{running.value=false}}
function formatSql(){editor.value?.getAction('editor.action.formatDocument')?.run()}
async function refreshBundle(){if(!file.value)return;bundle.value=await developmentApi.bundle(file.value.id);releases.value=await developmentApi.bundleReleases(file.value.id)}

async function openSchedule(){if(!file.value)return;infoOpen.value=false;scheduleOpen.value=true;if(!schedule.value)await loadTaskMeta();if(schedule.value)fillSchedule(schedule.value)}
function openInfo(){scheduleOpen.value=false;infoOpen.value=true}
function closeDrawers(){scheduleOpen.value=false;infoOpen.value=false}
async function onScheduleSourceChange(){sourceId.value=scheduleForm.dataSourceId;await loadDatabases();scheduleForm.databaseName=databases.value[0]||''}
function syncCron(){const t=scheduleForm.executionTime||'02:00', [h,m]=t.split(':').map(Number);if(scheduleForm.cycleType==='DAILY')scheduleForm.cronExpression=`0 ${m||0} ${h||0} * * ?`;else if(scheduleForm.cycleType==='HOURLY')scheduleForm.cronExpression=`0 ${m||0} * * * ?`;else if(scheduleForm.cycleType==='WEEKLY')scheduleForm.cronExpression=`0 ${m||0} ${h||0} ? * MON`;else if(scheduleForm.cycleType==='MONTHLY')scheduleForm.cronExpression=`0 ${m||0} ${h||0} 1 * ?`}
async function saveSchedule(){if(!file.value||!scheduleForm.dataSourceId)return ElMessage.warning('请选择 StarRocks 数据源');scheduleSaving.value=true;try{schedule.value=await developmentApi.saveSchedule(file.value.id,{...scheduleForm,dataSourceId:scheduleForm.dataSourceId,upstreamFileIds:[...scheduleForm.upstreamFileIds]});fillSchedule(schedule.value);await refreshBundle();ElMessage.success(`调度已保存为 S${schedule.value.currentVersion}，等待统一发布`)}catch(e){ElMessage.error(msg(e))}finally{scheduleSaving.value=false}}

async function loadLineage(){if(!file.value)return;try{lineage.value=await metadataApi.lineage(currentName.value)}catch{lineage.value=[]}}
async function switchBottom(v:typeof activeBottom.value){activeBottom.value=v;if(v==='lineage')await loadLineage();if(v==='versions'&&file.value){versions.value=await developmentApi.versions(file.value.id);await refreshBundle()}}

async function createTask(){if(!projectId.value||!newTask.name.trim())return;try{const base=newTask.name.trim().replace(/\s+/g,'_').replace(/\.sql$/i,'');const name=`${newTask.layer.toLowerCase()}_${base.replace(/^(ods|dwd|dws|ads)_/i,'')}.sql`;const created=await developmentApi.createFile({projectId:projectId.value,name,fileType:'SQL',content:`-- ${name.replace(/\.sql$/,'')}\n\nSELECT\n    *\nFROM \nWHERE 1 = 1;`,description:newTask.description});newTaskOpen.value=false;newTask.name='';newTask.description='';await loadFiles(created.id);if(newTask.configureSchedule)await openSchedule();ElMessage.success('开发任务已创建')}catch(e){ElMessage.error(msg(e))}}

function openPublish(){if(!file.value)return;publishRemark.value='统一发布 SQL 与调度配置';publishOpen.value=true}
async function publishBundle(){if(!file.value)return;try{const req=await releaseApi.request({resourceType:'DEVELOPMENT',resourceId:file.value.id,resourceName:file.value.name,requestedVersion:file.value.currentVersion,payload:{remark:publishRemark.value,scheduleVersion:bundle.value?.scheduleVersion||0}});publishOpen.value=false;if(req.status==='PENDING_APPROVAL')ElMessage.success('发布申请已提交，等待审批');else ElMessage.success('SQL 与调度已统一发布');await loadTaskMeta()}catch(e){ElMessage.error(msg(e))}}
function showRelease(r:DevelopmentBundleRelease){selectedRelease.value=r;releaseDetailOpen.value=true}
async function rollbackRelease(){if(!file.value||!selectedRelease.value)return;try{await ElMessageBox.confirm(`确认将生产整体回滚到 P${selectedRelease.value.releaseNo}？SQL 与调度会一起回滚。`,'整体回滚',{type:'warning'});await developmentApi.rollbackBundle(file.value.id,selectedRelease.value.releaseNo);releaseDetailOpen.value=false;await loadTaskMeta();ElMessage.success(`已回滚到 P${selectedRelease.value.releaseNo}`)}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(msg(e))}}

async function closeTab(tab:DevFile,e:Event){e.stopPropagation();if(tab.id===file.value?.id&&sqlDirty.value){try{await ElMessageBox.confirm('当前 SQL 有未保存修改，确认关闭？','关闭任务',{type:'warning'})}catch{return}}const idx=openFiles.value.findIndex(x=>x.id===tab.id);openFiles.value.splice(idx,1);if(tab.id===file.value?.id){const next=openFiles.value[Math.max(0,idx-1)];if(next)await openFile(next);else{file.value=undefined;setEditorContent('-- 请选择开发任务')}}}

watch(sourceId,()=>{if(!scheduleOpen.value)void loadDatabases()})
onMounted(boot);onBeforeUnmount(()=>editor.value?.dispose())
</script>

<template>
<div class="dev-ide">
  <div class="workbench">
    <aside class="sidebar">
      <div class="side-head"><strong>开发目录</strong><el-button type="primary" size="small" :icon="Plus" @click="newTaskOpen=true">新建</el-button></div>
      <div class="side-search"><el-input v-model="treeSearch" size="small" placeholder="搜索开发任务..." :prefix-icon="Search" clearable/></div>
      <div class="group-switch"><button v-for="x in [{k:'all',n:'全部'},{k:'recent',n:'最近打开'},{k:'mine',n:'我的任务'}]" :key="x.k" :class="['pill',{active:groupMode===x.k}]" @click="groupMode=x.k as any">{{x.n}}</button></div>
      <div class="tree">
        <template v-for="g in groupedFiles" :key="g.layer"><div class="tree-row level1"><span class="chev">⌄</span><el-icon><Folder/></el-icon><b>{{g.layer==='OTHER'?'其他':g.layer}}</b></div><button v-for="f in g.rows" :key="f.id" class="tree-row level2 task" :class="{selected:file?.id===f.id}" @click="openFile(f)"><span class="sql-ico">SQL</span><span class="task-name">{{f.name.replace(/\.sql$/i,'')}}</span><span :class="['task-state',stateClass(f)]"></span></button></template>
      </div>
      <div class="side-foot">生产空间 · 单一工作空间</div>
    </aside>

    <main class="main">
      <div class="tabs"><button v-for="tab in openFiles" :key="tab.id" :class="['tab',{active:file?.id===tab.id,dirty:file?.id===tab.id&&sqlDirty}]" @click="openFile(tab)"><span class="dot"></span><span>{{tab.name}}</span><el-icon class="close" @click="closeTab(tab,$event)"><Close/></el-icon></button><button class="plus-tab" @click="newTaskOpen=true">＋</button></div>
      <div class="editor-toolbar">
        <div class="file-meta"><span class="file-title">{{currentName}}</span><span class="badge dev">SQL V{{file?.currentVersion||0}}</span><span class="badge schedule">调度 S{{bundle?.scheduleVersion||0}}</span><span class="badge prod">生产 P{{bundle?.releaseNo||0}} · V{{publishedSql}}/S{{publishedSchedule}}</span><span :class="['badge',unsavedCount?'dirty':'prod']">{{unsavedCount?`● ${unsavedCount} 项未发布`:'✓ 与生产一致'}}</span></div>
        <div class="toolbar-actions"><el-button size="small" :loading="saving" @click="saveSql">保存 <span class="shortcut">Ctrl+S</span></el-button><el-button size="small" class="run" :loading="running" @click="runSql">▶ 运行</el-button><el-button size="small" @click="formatSql">格式化</el-button><el-button size="small" @click="openSchedule">调度配置</el-button><el-button size="small" @click="openInfo">任务信息</el-button><el-button size="small" type="primary" @click="openPublish">提交发布</el-button></div>
      </div>

      <div class="editor-area" :class="{'schedule-open':scheduleOpen,'info-open':infoOpen}">
        <div class="code-wrap"><div ref="editorHost" class="editor-host"></div><div v-if="editorLoading&&!editor" class="editor-loading">正在加载 SQL 编辑器…</div></div>
        <aside v-if="infoOpen" class="right-drawer info-drawer"><div class="drawer-head"><strong>任务信息</strong><button @click="closeDrawers">×</button></div><div class="drawer-body"><dl class="kv"><dt>任务名称</dt><dd>{{currentName}}</dd><dt>任务类型</dt><dd>StarRocks SQL</dd><dt>负责人</dt><dd>{{projects.find(x=>x.id===projectId)?.ownerName||'admin'}}</dd><dt>SQL 版本</dt><dd>V{{file?.currentVersion||0}}</dd><dt>调度版本</dt><dd>S{{bundle?.scheduleVersion||0}}</dd><dt>生产发布</dt><dd>P{{bundle?.releaseNo||0}}</dd></dl><div class="divider"></div><div class="form-item"><label>任务描述</label><textarea :value="file?.description||''" readonly/></div><div class="divider"></div><div class="section-title">当前生产配置</div><dl class="kv"><dt>代码</dt><dd>SQL V{{publishedSql}}</dd><dt>调度</dt><dd>S{{publishedSchedule}} · {{cycleLabel(schedule?.cycleType||'DAILY')}} {{schedule?.executionTime||'—'}}</dd><dt>数据源</dt><dd>{{currentSourceName}}</dd><dt>数据库</dt><dd>{{database||'—'}}</dd></dl><span class="link" @click="switchBottom('versions');closeDrawers()">查看发布历史 →</span></div></aside>

        <aside v-if="scheduleOpen" class="right-drawer schedule-drawer"><div class="drawer-head"><strong>调度配置 <span class="schedule-version">S{{bundle?.scheduleVersion||0}}</span></strong><button @click="closeDrawers">×</button></div><div class="drawer-body schedule-body">
          <div class="schedule-summary"><div class="row"><span>调度状态</span><span><el-switch v-model="scheduleForm.enabled"/> <b>{{scheduleForm.enabled?'已启用':'已停用'}}</b></span></div><div class="row"><span>生产生效版本</span><span>P{{bundle?.releaseNo||0}} · S{{publishedSchedule}}</span></div><div class="row"><span>当前状态</span><span :class="bundle?.scheduleDirty?'warn':'ok'">{{bundle?.scheduleDirty?'有未发布修改':'与生产一致'}}</span></div></div>
          <div class="section-title">运行环境</div><div class="inline-grid"><div class="form-item"><label>StarRocks 数据源</label><el-select v-model="scheduleForm.dataSourceId" filterable @change="onScheduleSourceChange"><el-option v-for="s in sources" :key="s.id" :label="s.name" :value="s.id"/></el-select></div><div class="form-item"><label>Database</label><el-select v-model="scheduleForm.databaseName" filterable><el-option v-for="d in databases" :key="d" :label="d" :value="d"/></el-select></div></div>
          <div class="divider"></div><div class="section-title">基本调度</div><div class="inline-grid"><div class="form-item"><label>调度周期</label><el-select v-model="scheduleForm.cycleType" @change="syncCron"><el-option label="每日" value="DAILY"/><el-option label="每小时" value="HOURLY"/><el-option label="每周" value="WEEKLY"/><el-option label="每月" value="MONTHLY"/><el-option label="自定义 Cron" value="CRON"/></el-select></div><div class="form-item"><label>执行时间</label><el-time-picker v-model="scheduleForm.executionTime" value-format="HH:mm" format="HH:mm" style="width:100%" @change="syncCron"/></div></div><div class="form-item"><label>Cron 表达式 <span class="muted">（高级）</span></label><el-input v-model="scheduleForm.cronExpression"/></div>
          <div class="divider"></div><div class="section-title"><span>上游依赖</span><span class="muted">成功后触发语义</span></div><div class="form-item"><el-select v-model="scheduleForm.upstreamFileIds" multiple filterable collapse-tags placeholder="选择上游开发任务"><el-option v-for="f in upstreamOptions" :key="f.id" :label="f.name.replace(/\.sql$/i,'')" :value="f.id"/></el-select></div><div class="dep-list"><div v-for="d in scheduleDependencies" :key="d.fileId" class="dep-item"><span>↳</span><b>{{d.name.replace(/\.sql$/i,'')}}</b><span class="dep-status">已配置</span></div><div v-if="!scheduleDependencies.length" class="dep-empty">暂无已保存上游依赖</div></div>
          <div class="divider"></div><div class="section-title">运行参数</div><div class="form-item"><label>biz_date</label><el-select v-model="scheduleForm.bizDateParam"><el-option label="${system.biz.date-1}" value="${system.biz.date-1}"/><el-option label="${system.biz.date}" value="${system.biz.date}"/><el-option label="${system.date}" value="${system.date}"/></el-select></div>
          <div class="divider"></div><div class="section-title">失败策略</div><div class="inline-grid"><div class="form-item"><label>失败重试次数</label><el-input-number v-model="scheduleForm.retryTimes" :min="0" :max="20" controls-position="right"/></div><div class="form-item"><label>重试间隔（分钟）</label><el-input-number v-model="scheduleForm.retryIntervalMinutes" :min="1" :max="1440" controls-position="right"/></div></div><div class="form-item"><label>超时时间（分钟）</label><el-input-number v-model="scheduleForm.timeoutMinutes" :min="1" :max="10080" controls-position="right"/></div>
          <div class="drawer-actions"><el-button @click="closeDrawers">取消</el-button><el-button type="primary" :loading="scheduleSaving" @click="saveSchedule">保存调度配置</el-button></div>
        </div></aside>
      </div>

      <section class="bottom"><div class="bottom-tabs"><div class="bottom-left"><button v-for="x in [{k:'result',n:'运行结果'},{k:'log',n:'执行日志'},{k:'lineage',n:'数据血缘'},{k:'schedule',n:'调度依赖'},{k:'versions',n:'发布版本'}]" :key="x.k" :class="['bottom-tab',{active:activeBottom===x.k}]" @click="switchBottom(x.k as any)">{{x.n}}</button></div><div class="status-line">{{result?.status==='SUCCESS'?`✓ 最近执行成功 · ${result.elapsedMs} ms · ${result.rowCount} 行`:'运行 SQL 后查看结果'}}</div></div><div class="bottom-content">
        <div v-if="activeBottom==='result'"><el-table v-if="result?.rows?.length" :data="result.rows" height="190" size="small"><el-table-column v-for="c in result.columns" :key="c" :prop="c" :label="c" min-width="130"/></el-table><div v-else class="empty">暂无运行结果</div></div>
        <pre v-else-if="activeBottom==='log'" class="log">{{logText}}</pre>
        <div v-else-if="activeBottom==='lineage'" class="lineage"><template v-if="lineage.length"><div v-for="(x,i) in lineage" :key="x.id" class="lineage-item"><div class="node"><b>{{x.sourceTable}}</b><span>上游表</span></div><div class="arrow">→</div><div class="node current"><b>{{x.targetTable}}</b><span>当前任务</span></div><div v-if="i<lineage.length-1" class="arrow">·</div></div></template><div v-else class="empty">暂无数据血缘</div></div>
        <div v-else-if="activeBottom==='schedule'" class="dag-wrap"><div class="dag"><div class="dag-col"><div v-for="d in scheduleDependencies" :key="d.fileId" class="dag-node"><span>上游</span><b>{{d.name.replace(/\.sql$/i,'')}}</b></div></div><div class="dag-arrow">→</div><div class="dag-node current"><span>当前</span><b>{{currentName}}</b><small>{{cycleLabel(schedule?.cycleType||'DAILY')}} {{schedule?.executionTime||'—'}} · S{{bundle?.scheduleVersion||0}}</small></div><div class="dag-arrow">→</div><div class="dag-col"><div v-for="d in scheduleDownstream" :key="d.fileId" class="dag-node"><span>下游</span><b>{{d.name.replace(/\.sql$/i,'')}}</b></div></div></div></div>
        <div v-else class="version-list"><div class="version-row head"><span>发布版本</span><span>状态</span><span>SQL</span><span>调度</span><span>修改人</span><span>时间</span><span>变更说明</span><span>操作</span></div><div v-if="unsavedCount" class="version-row"><b>待发布</b><span><i class="vtag current">开发中</i></span><span>V{{file?.currentVersion||0}}</span><span>S{{bundle?.scheduleVersion||0}}</span><span>当前用户</span><span>当前</span><span>{{bundle?.sqlDirty||sqlDirty?'SQL ':''}}{{bundle?.scheduleDirty?'调度 ':''}}存在未发布修改</span><span><a @click="openPublish">发布</a></span></div><div v-for="r in releases" :key="r.releaseNo" class="version-row"><b>P{{r.releaseNo}}</b><span><i :class="['vtag',r.current?'prod':'saved']">{{r.current?'当前生产':'历史'}}</i></span><span>V{{r.sqlVersion}}</span><span>S{{r.scheduleVersion}}</span><span>{{r.operatorName}}</span><span>{{fmt(r.releasedAt)}}</span><span>{{r.remark||'统一发布'}}</span><span><a @click="showRelease(r)">详情</a></span></div></div>
      </div></section>
      <div class="statusbar"><div><span class="green-dot"></span>StarRocks 已连接 <span>{{currentSourceName}}</span><span>{{database||'—'}}</span></div><div><span>UTF-8</span><span>SQL</span><span>统一发布版本</span></div></div>
    </main>
  </div>

  <el-dialog v-model="newTaskOpen" title="新建开发任务" width="540px"><el-form label-position="top"><div class="dialog-grid"><el-form-item label="任务名称 *"><el-input v-model="newTask.name" placeholder="例如：order_detail"/></el-form-item><el-form-item label="任务类型 *"><el-select model-value="STARROCKS_SQL" disabled><el-option label="StarRocks SQL" value="STARROCKS_SQL"/></el-select></el-form-item><el-form-item label="目录 *"><el-select v-model="newTask.layer"><el-option v-for="x in ['ODS','DWD','DWS','ADS']" :key="x" :label="x" :value="x"/></el-select></el-form-item><el-form-item label="负责人"><el-input :model-value="projects.find(x=>x.id===projectId)?.ownerName||'admin'" disabled/></el-form-item></div><el-form-item label="任务描述"><el-input v-model="newTask.description" type="textarea"/></el-form-item><el-checkbox v-model="newTask.configureSchedule">创建后立即配置调度</el-checkbox></el-form><template #footer><el-button @click="newTaskOpen=false">取消</el-button><el-button type="primary" @click="createTask">创建并打开</el-button></template></el-dialog>

  <el-dialog v-model="publishOpen" title="提交发布 · SQL / 调度统一发布" width="820px"><div class="release-strip"><strong>P{{(bundle?.releaseNo||0)+1}}</strong><span>=</span><span>SQL V{{file?.currentVersion||0}}</span><span>+</span><span>调度 S{{bundle?.scheduleVersion||0}}</span><span class="push-right">当前生产 P{{bundle?.releaseNo||0}}</span></div><el-form label-position="top"><div class="dialog-grid"><el-form-item label="任务名称"><el-input :model-value="currentName" disabled/></el-form-item><el-form-item label="变更说明 *"><el-input v-model="publishRemark"/></el-form-item></div></el-form><div class="check-title">发布前检查</div><div class="checks"><div><span>SQL 已保存</span><b class="ok">{{sqlDirty?'需先保存':'✓ 通过'}}</b></div><div><span>调度表达式</span><b class="ok">✓ Quartz Cron</b></div><div><span>StarRocks 数据源</span><b class="ok">{{scheduleForm.dataSourceId?'✓ 已配置':'未配置'}}</b></div><div><span>任务依赖</span><b class="ok">✓ 已校验</b></div></div><div class="change-card"><div class="change-title">统一发布内容</div><div class="change-grid"><div><b>当前生产</b><p>SQL V{{publishedSql}}</p><p>调度 S{{publishedSchedule}}</p><p>P{{bundle?.releaseNo||0}}</p></div><div><b>本次发布</b><p>SQL V{{file?.currentVersion||0}}</p><p>调度 S{{bundle?.scheduleVersion||0}}</p><p>{{cycleLabel(schedule?.cycleType||'DAILY')}} {{schedule?.executionTime||'—'}}</p></div></div></div><template #footer><el-button @click="publishOpen=false">取消</el-button><el-button type="primary" :disabled="sqlDirty" @click="publishBundle">确认发布</el-button></template></el-dialog>

  <el-dialog v-model="releaseDetailOpen" :title="`发布版本 P${selectedRelease?.releaseNo||''}`" width="680px"><div v-if="selectedRelease" class="release-strip"><strong>P{{selectedRelease.releaseNo}}</strong><span>SQL V{{selectedRelease.sqlVersion}} + 调度 S{{selectedRelease.scheduleVersion}}</span><span class="push-right">{{selectedRelease.current?'当前生产':'历史'}}</span></div><div v-if="selectedRelease" class="change-grid release-detail"><div><b>代码版本</b><p>SQL V{{selectedRelease.sqlVersion}}</p></div><div><b>调度配置</b><p>S{{selectedRelease.scheduleVersion}}</p><p>{{selectedRelease.remark||'统一发布'}}</p></div></div><template #footer><el-button @click="releaseDetailOpen=false">关闭</el-button><el-button v-if="selectedRelease&&!selectedRelease.current" type="primary" @click="rollbackRelease">回滚到此发布版本</el-button></template></el-dialog>
</div>
</template>

